# =====================================================================
#  restaurant.map - phishing phrases for restaurants, cafes, bars,
#  bakeries and catering companies
#  Part of: phywall by Develust Technology
#
#  Format : one regex per line, /pattern/flags (i = case-insensitive,
#           u = UTF-8). No trailing spaces.
#  Note   : PHISH_TEXT scores 0 alone; it only adds points together
#           with a phishing link (PHISH_URL / PHISHING).
#
#  Themes : fake "food poisoning" / foreign object complaints with
#           photo, video or medical report "evidence", fake health
#           inspection and hygiene notices, food delivery partner
#           account suspension (Wolt, Glovo, Uber Eats, Bolt Food,
#           Deliveroo, DoorDash, Just Eat, Yemeksepeti), review
#           platform threats (TripAdvisor, Google reviews), fake large
#           group / catering bookings with "menu requirements" files,
#           POS / payment terminal and supplier bank changes
#
#  Avoided: normal guest mails ("table for 4 on Friday", "do you have
#           vegan options", "menu attached"), because restaurants
#           receive them every day.
# =====================================================================

# ===== English =====
# Food poisoning / foreign object complaints
/(we|i|my\s+(family|wife|husband|son|daughter|kids?|children|guests?))\s+(got|became|were|was)\s+(sick|ill|hospitali[sz]ed)\s+(after|from)\s+(eating|dining|the\s+(food|meal|dinner|lunch))\s+(at|in|from)\s+your\s+(restaurant|cafe|place|establishment)/i
/food\s+poisoning\s+(complaint|case|incident|report|claim)\s+(regarding|against|about)\s+your\s+(restaurant|cafe|business|establishment)/i
/(found|there\s+was)\s+(a|an)\s+(hair|insect|cockroach|bug|worm|glass|plastic|metal|foreign\s+object)\s+in\s+(my|our|the)\s+(food|meal|dish|order|plate|soup|salad)[^.]{0,60}(photo|picture|video|attached|link|see)/i
/(see|view|check|download)\s+(the\s+)?(photos?|pictures?|videos?|medical\s+(report|certificate)|hospital\s+(report|bill)|lab\s+results?)\s+(of|from|about)\s+(the\s+)?(food|meal|dish|incident|poisoning)/i
/(i|we)\s+will\s+(report|sue|post\s+about|expose)\s+(you|your\s+(restaurant|cafe|business))[^.]{0,40}(health\s+(department|inspector|authority)|food\s+safety|social\s+media|unless)/i
# Health inspection / hygiene
/(health|hygiene|sanitary|food\s+safety)\s+inspection\s+(report|result|notice|findings)\s+(for\s+your\s+(restaurant|establishment|premises)\s+)?(is\s+)?(available|attached|ready|pending)/i
/(your\s+)?(food\s+(business|hygiene)|restaurant|establishment)\s+(license|licence|permit|rating|certificate)\s+(has\s+been\s+|will\s+be\s+|is\s+)?(suspended|revoked|expired|downgraded|under\s+review)/i
/(unannounced|surprise|scheduled)\s+(health|hygiene|sanitary)\s+inspection\s+[^.]{0,40}(confirm|download|review|checklist|documents)/i
# Delivery platforms
/(wolt|glovo|uber\s*eats|bolt\s+food|deliveroo|doordash|grubhub|just\s+eat|foodpanda|yemeksepeti|talabat|getir|trendyol\s+yemek)\s+(partner|merchant|restaurant|store|venue)\s+(account|profile|listing|portal)\s+(has\s+been\s+|will\s+be\s+|is\s+)?(suspended|deactivated|restricted|paused|closed|on\s+hold|locked)/i
/(your\s+)?(restaurant|store|venue|menu)\s+(has\s+been\s+|was\s+)?(removed|delisted|hidden|paused)\s+from\s+(wolt|glovo|uber\s*eats|bolt\s+food|deliveroo|doordash|just\s+eat|foodpanda|yemeksepeti|talabat)/i
/(update|verify|confirm)\s+your\s+(partner|merchant|restaurant)\s+(bank|payout|payment)\s+(details|information|account)\s+(to\s+(avoid|continue|receive)|before)/i
/(weekly|monthly|pending)\s+(payout|settlement|payment)\s+(for\s+your\s+(restaurant|store|orders)\s+)?(is\s+)?(on\s+hold|blocked|failed|pending\s+verification)/i
# Review threats
/(tripadvisor|google|yelp|zomato)\s+(review|listing|business\s+profile)[^.]{0,30}(suspended|removed|flagged|reported|violation)/i
/(negative|1-star|one\s+star|bad)\s+reviews?\s+(will\s+be\s+)?(posted|published|removed)[^.]{0,40}(unless|pay|payment|contact\s+us|bitcoin)/i
/(remove|delete)\s+(negative|bad|fake)\s+reviews?\s+(from\s+your\s+(tripadvisor|google|yelp)\s+(page|profile|listing))/i
# Fake group / catering bookings
/(large|corporate|group|private)\s+(booking|reservation|event|party|dinner)\s+for\s+\d{2,3}\s+(guests|people|persons|pax)[^.]{0,80}(menu\s+requirements|details|list)\s+(attached|in\s+the\s+(link|document)|via\s+(the\s+)?link)/i
/(catering|event)\s+(order|request|inquiry)[^.]{0,40}(view|download|open)\s+(the\s+)?(order|requirements|specifications|purchase\s+order|po)\s+(document|file|here|below)/i
# POS / supplier
/(pos|payment\s+terminal|card\s+terminal|card\s+machine)\s+(will\s+be\s+|has\s+been\s+)?(deactivated|blocked|suspended)[^.]{0,30}(update|verify|confirm)/i
/(food|beverage|meat|produce|wine)\s+supplier\s+[^.]{0,30}(new|changed|updated)\s+(bank|banking|account)\s+(details|information)/i

